module arpa_land (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] n,\n    input wire [2:0] crush_0,\n    input wire [2:0] crush_1,\n    input wire [2:0] crush_2,\n    input wire [2:0] crush_3,\n    input wire [2:0] crush_4,\n    input wire [2:0] crush_5,\n    input wire [2:0] crush_6,\n    input wire [2:0] crush_7,\n    output reg [9:0] result,\n    output reg done\n);\n\n    localparam [3:0] S_IDLE   = 4'd0;\n    localparam [3:0] S_INIT   = 4'd1;\n    localparam [3:0] S_CHECK  = 4'd2;\n    localparam [3:0] S_TRAVERSE = 4'd3;\n    localparam [3:0] S_ADJUST = 4'd4;\n    localparam [3:0] S_NEXT   = 4'd5;\n    localparam [3:0] S_COMPUTE = 4'd6;\n    localparam [3:0] S_DONE   = 4'd7;\n    localparam [3:0] S_ERROR  = 4'd8;\n\n    reg [3:0] state;\n    reg [2:0] n_reg;\n    reg [2:0] crush_reg [0:7];\n    reg visited [0:7];\n    reg [2:0] i;\n    reg [2:0] current;\n    reg [2:0] start_node;\n    reg [3:0] count;\n    reg [1:0] max2;\n    reg max3;\n    reg max5;\n    reg max7;\n    reg error;\n    reg [3:0] next_state;\n    integer idx;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 10'd0;\n            n_reg <= 3'd0;\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                crush_reg[idx] <= 3'd0;\n                visited[idx] <= 1'b0;\n            end\n            i <= 3'd0;\n            current <= 3'd0;\n            start_node <= 3'd0;\n            count <= 4'd0;\n            max2 <= 2'd0;\n            max3 <= 1'b0;\n            max5 <= 1'b0;\n            max7 <= 1'b0;\n            error <= 1'b0;\n            next_state <= S_IDLE;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    error <= 1'b0;\n                    result <= 10'd0;\n                    if (start) begin\n                        n_reg <= (n > 3'd0 && n <= 3'd8) ? n : 3'd8;\n                        crush_reg[0] <= crush_0;\n                        crush_reg[1] <= crush_1;\n                        crush_reg[2] <= crush_2;\n                        crush_reg[3] <= crush_3;\n                        crush_reg[4] <= crush_4;\n                        crush_reg[5] <= crush_5;\n                        crush_reg[6] <= crush_6;\n                        crush_reg[7] <= crush_7;\n                        state <= S_INIT;\n                    end\n                end\n                \n                S_INIT: begin\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        visited[idx] <= (idx < n_reg) ? 1'b0 : 1'b1;\n                    end\n                    i <= 3'd0;\n                    max2 <= 2'd0;\n                    max3 <= 1'b0;\n                    max5 <= 1'b0;\n                    max7 <= 1'b0;\n                    state <= S_CHECK;\n                end\n                \n                S_CHECK: begin\n                    if (i < n_reg) begin\n                        if (!visited[i]) begin\n                            current <= i;\n                            start_node <= i;\n                            count <= 4'd0;\n                            state <= S_TRAVERSE;\n                        end else begin\n                            i <= i + 3'd1;\n                            state <= S_CHECK;\n                        end\n                    end else begin\n                        state <= (error) ? S_ERROR : S_COMPUTE;\n                    end\n                end\n                \n                S_TRAVERSE: begin\n                    if (!visited[current]) begin\n                        visited[current] <= 1'b1;\n                        current <= crush_reg[current];\n                        count <= count + 4'd1;\n                    end else begin\n                        if (current == start_node) begin\n                            state <= S_ADJUST;\n                        end else begin\n                            error <= 1'b1;\n                            state <= S_CHECK;\n                        end\n                    end\n                end\n                \n                S_ADJUST: begin\n                    if (count[0] == 1'b0) count <= count >> 1;\n                    case (count)\n                        4'd2: if (max2 < 2'd1) max2 <= 2'd1;\n                        4'd3: max3 <= 1'b1;\n                        4'd4: if (max2 < 2'd2) max2 <= 2'd2;\n                        4'd5: max5 <= 1'b1;\n                        4'd7: max7 <= 1'b1;\n                        default: if (count != 4'd1) error <= 1'b1;\n                    endcase\n                    i <= i + 3'd1;\n                    state <= S_CHECK;\n                end\n                \n                S_COMPUTE: begin\n                    result <= (10'd1 << max2) * \n                             (max3 ? 10'd3 : 10'd1) * \n                             (max5 ? 10'd5 : 10'd1) * \n                             (max7 ? 10'd7 : 10'd1);\n                    state <= S_DONE;\n                end\n                \n                S_DONE: begin\n                    done <= 1'b1;\n                    if (error) result <= 10'h3FF;\n                end\n                \n                S_ERROR: begin\n                    error <= 1'b1;\n                    state <= S_DONE;\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\nendmodule